// Validate checks that Total equals the sum of the line amounts.
func (o Order) Validate() error {
	var sum int64
	for _, l := range o.Lines {
		sum += l.Amount
	}
	if sum != o.Total {
		return fmt.Errorf("order %s: total %d != line sum %d", o.ID, o.Total, sum)
	}
	return nil
}

